  /*Definition: The orderItem operation handles its intended business action in this system.
   *Precondition: Required inputs are present, referenced data is valid, and the action is allowed by business rules.
   *Postcondition: The system applies the requested outcome, keeps data consistent, and returns the defined result.*/
  orderItem(barcode: number, quantity: number): boolean {
    /*Definition Start*/
    let item: Item = l({
      logic: () =>
        getRepository(Item).find(
          (i: Item) =>
            l({
              logic: () => i.Barcode === barcode,
              description: "i.Barcode=barcode",
            }).build().pass,
        ),
      description: "Item.allInstance()->any(i:Item|i.Barcode=barcode)",
    }).build().pass;
    let orderProduct: OrderProduct = l({
      logic: () => this.CurrentOrderProduct,
      description: "self.CurrentOrderProduct",
    }).build().pass;
    let orderEntry: OrderEntry = l({
      logic: () =>
        getRepository(OrderEntry).find(
          (oe: OrderEntry) =>
            l({
              logic: () => oe.Item === item,
              description: "oe.Item=item",
            }).build().pass,
        ),
      description: "OrderEntry.allInstance()->any(oe:OrderEntry|oe.Item=item)",
    }).build().pass;
    /*Definition End*/

    /*Precondition Start*/
    const { errorMessage: preconditionErrorMessage, pass: isPreconditionPass } =
      l({
        logic: () => StandardOPs.oclIsUndefined(item) === false,
        description: "item.oclIsUndefined()=false",
      })
        .and({
          logic: () => StandardOPs.oclIsUndefined(orderProduct) === false,
          description: "orderProduct.oclIsUndefined()=false",
        })
        .and({
          logic: () => quantity > 0,
          description: "quantity>0",
        })
        .build();
    if (!isPreconditionPass) {
      throw new PreconditionError(preconditionErrorMessage);
    }
    /*Precondition End*/

    /*Postcondition Start*/
    let newEntry: OrderEntry;
    return l({
      execute: () => (newEntry = new OrderEntry()),
      description: "newEntry.oclIsNew()",
    })
      .and({
        execute: () => getRepository(OrderEntry).push(newEntry),
        description: "OrderEntry.allInstance()->includes(newEntry)",
      })
      .and({
        execute: () => (newEntry.Quantity = quantity),
        description: "newEntry.Quantity=quantity",
      })
      .and({
        execute: () => (newEntry.SubAmount = quantity * item.OrderPrice),
        description: "newEntry.SubAmount=quantity*item.OrderPrice",
      })
      .and({
        execute: () => (newEntry.Item = item),
        description: "newEntry.Item=item",
      })
      .and({
        execute: () => orderProduct.ContainedEntries.push(newEntry),
        description: "orderProduct.ContainedEntries->includes(newEntry)",
      })
      .and({
        execute: () => (orderProduct.Amount = orderProduct.Amount + quantity),
        description: "orderProduct.Amount=orderProduct.Amount@pre+quantity",
      })
      .build().value;
    /*Postcondition End*/
  }
}
